import json,math,itertools,random,os,sys
from pathlib import Path
sys.path.insert(0,'/app/tools'); from check_plan import distance,evaluate

def make(o,order,mode,seed):
 d=o['depot']; left={c['id']:c for c in o['customers']}; routes=[]; rng=random.Random(seed)
 fs={f['type']:f for f in o['fleet']}
 for typ in order:
  k=fs[typ]
  for z in range(k['count']):
   if not left: break
   clock=d['open']; here=d; load=driven=0; stops=[]
   while 1:
    opts=[]
    for c in left.values():
     leg=distance(here,c); st=max(clock+leg*k['pace'],c['ready'])
     tot=driven+leg+distance(c,d); back=st+c['service']+distance(c,d)*k['pace']
     if load+c['demand']>k['capacity'] or st>c['due'] or back>d['close'] or back-d['open']>k['shift'] or (k['range'] is not None and tot>k['range']): continue
     if mode==0: score=leg
     elif mode==1: score=leg+.03*max(0,c['ready']-(clock+leg*k['pace']))
     elif mode==2: score=c['due']+.8*leg*k['pace']
     elif mode==3: score=leg-2*c['demand']+rng.random()*30
     else: score=c['due']+.3*leg*k['pace']+rng.random()*900
     opts.append((score,c,leg,st))
    if not opts: break
    _,c,leg,st=min(opts,key=lambda x:x[0]); stops.append(c['id']); load+=c['demand']; driven+=leg; clock=st+c['service']; here=c; del left[c['id']]
   if stops: routes.append({'type':typ,'depart':d['open'],'stops':stops})
 return {'routes':routes}

for name in ['harbour-lanes','old-town','riverside','north-ring']:
 o=json.load(open('/app/orders/'+name+'.json')); best=None
 # preserve any feasible current plan
 try:
  p=json.load(open('/app/plans/'+name+'.json')); best=(evaluate(o,p),p,'existing')
 except: pass
 for order in itertools.permutations(['bike','van','truck']):
  for mode in range(5):
   for seed in range(4):
    p=make(o,order,mode,seed)
    try: cost=evaluate(o,p)
    except: continue
    if best is None or cost<best[0]: best=(cost,p,(order,mode,seed)); print(name,best[0],best[2],flush=True)
 if best:
  json.dump(best[1],open('/app/plans/'+name+'.json','w'),indent=1); print(name,'BEST',best[0],best[2])
 else: print(name,'NO FEASIBLE')
